-- A recorded expense alone never clears a payment. This adds an independently
-- checked loss disposition to the existing separate human release workflow.
CREATE FUNCTION public.provider_dispute_resolution_eligible(s jsonb,identity_ok boolean,pages_complete boolean) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE k jsonb;l record;actual jsonb;debits numeric;returns numeric;factor numeric;BEGIN
 IF identity_ok IS DISTINCT FROM true OR pages_complete IS DISTINCT FROM true OR s IS NULL OR s ? 'unavailable' OR s->'disputeAttentionRetained' IS DISTINCT FROM 'true'::jsonb OR s->'onIsFuture' IS DISTINCT FROM 'false'::jsonb OR s->'onPrecedesCollection' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(s->'cases') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'movements') IS DISTINCT FROM 'array' OR jsonb_typeof(s->'disputedAssets') IS DISTINCT FROM 'array' OR jsonb_array_length(s->'cases') NOT BETWEEN 1 AND 100 OR jsonb_array_length(s->'movements') NOT BETWEEN 1 AND 200 THEN RETURN false;END IF;
 IF(SELECT count(*)<>count(DISTINCT value->>'disputeId') FROM jsonb_array_elements(s->'cases')) OR(SELECT count(*)<>count(DISTINCT value->>'balanceTransactionId') FROM jsonb_array_elements(s->'movements')) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m LEFT JOIN LATERAL(SELECT value FROM jsonb_array_elements(s->'cases') WHERE value->>'disputeId'=m->>'disputeId') c ON true WHERE c.value IS NULL OR m->'observed' IS DISTINCT FROM 'true'::jsonb OR m->'recognized' IS DISTINCT FROM 'true'::jsonb OR m->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR m->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR m->'amountMatched' IS DISTINCT FROM 'true'::jsonb OR m->'accountingMatchesLatest' IS DISTINCT FROM 'true'::jsonb OR m->'futureDatedAccounting' IS DISTINCT FROM 'false'::jsonb OR m->>'postingId' IS NULL OR m->'currencyCode' IS DISTINCT FROM c.value->'currencyCode' OR m->'providerUnitScale' IS DISTINCT FROM c.value->'providerUnitScale') OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'disputedAssets') a WHERE a->>'balanceMinor' IS NULL OR(a->>'balanceMinor')::numeric<>0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'cases') c WHERE c->>'disputeId'=a->>'disputeId')) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM public.provider_dispute_losses loss WHERE loss.collection_id=(s->>'collectionId')::uuid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'cases') c WHERE c->>'disputeId'=loss.dispute_id)) THEN RETURN false;END IF;
 FOR k IN SELECT value FROM jsonb_array_elements(s->'cases') LOOP
  IF k->>'status' IS NULL OR k->>'status' NOT IN('won','warning_closed','prevented','lost') OR k->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR k->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR k->'exceedsOriginalAmount' IS DISTINCT FROM 'false'::jsonb OR k->>'providerUnitScale' IS NULL OR(k->>'amountMinor')::numeric<=0 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'disputedAssets') a WHERE a->>'disputeId'=k->>'disputeId') THEN RETURN false;END IF;
  SELECT coalesce(sum(-(m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric<0),0),coalesce(sum((m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric>0),0) INTO debits,returns FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=k->>'disputeId';
  IF debits<>(k->>'amountMinor')::numeric THEN RETURN false;END IF;
  IF k->>'status'<>'lost' THEN
   IF returns<>debits OR EXISTS(SELECT 1 FROM public.provider_dispute_losses loss WHERE loss.collection_id=(s->>'collectionId')::uuid AND loss.dispute_id=k->>'disputeId') THEN RETURN false;END IF;
  ELSE
   SELECT loss.*,p.status approval_status,p.action approval_action,p.reviewer_id,p.target_id,j.approval_id journal_approval,j.posted_by,j.posted_on journal_on,j.purpose,j.line_count,j.reverses_id,j.reference INTO l FROM public.provider_dispute_losses loss JOIN public.approval_requests p ON p.academy_id=loss.academy_id AND p.id=loss.approval_id JOIN public.finance_journals j ON j.academy_id=loss.academy_id AND j.id=loss.id WHERE loss.collection_id=(s->>'collectionId')::uuid AND loss.dispute_id=k->>'disputeId';
   IF l.id IS NULL OR returns>=debits OR l.posted_on>(s->>'on')::date OR l.approval_status IS DISTINCT FROM 'applied' OR l.approval_action IS DISTINCT FROM 'finance.provider-dispute.loss' OR l.reviewer_id IS DISTINCT FROM l.created_by OR l.target_id IS DISTINCT FROM l.id OR l.journal_approval IS DISTINCT FROM l.approval_id OR l.posted_by IS DISTINCT FROM l.created_by OR l.journal_on IS DISTINCT FROM l.posted_on OR l.purpose IS DISTINCT FROM 'activity' OR l.line_count<>2 OR l.reverses_id IS NOT NULL OR l.reference IS DISTINCT FROM 'provider-dispute-loss:'||l.id::text OR l.source->>'disposition' IS DISTINCT FROM 'academy_expense' OR l.source->>'taxTreatment' IS DISTINCT FROM 'not_claimed' OR l.source->'currencyCode' IS DISTINCT FROM k->'currencyCode' OR EXISTS(SELECT 1 FROM public.finance_journals v WHERE v.academy_id=l.academy_id AND v.reverses_id=l.id) THEN RETURN false;END IF;
   factor=power(10::numeric,(l.source->>'unitScale')::integer)/power(10::numeric,(k->>'providerUnitScale')::integer);
   IF l.amount_minor<>(debits-returns)*factor OR l.amount_minor IS DISTINCT FROM(l.source->>'amountMinor')::numeric OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=k->>'disputeId' AND(m->>'disputedAccountId' IS DISTINCT FROM l.disputed_account::text OR m->'accountingCurrencyId' IS DISTINCT FROM l.source->'currencyId' OR m->'accountingUnitScale' IS DISTINCT FROM l.source->'unitScale')) THEN RETURN false;END IF;
   SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=l.academy_id AND journal_id=l.id;
   IF actual IS DISTINCT FROM jsonb_build_array(jsonb_build_object('accountId',l.expense_account,'accountVersion',l.source->'expenseVersion','side','debit','amountMinor',trunc(l.amount_minor)::text),jsonb_build_object('accountId',l.disputed_account,'accountVersion',l.source->'disputedVersion','side','credit','amountMinor',trunc(l.amount_minor)::text)) THEN RETURN false;END IF;
  END IF;
 END LOOP;RETURN true;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $$;
-- Only a dispute-aspect predicate for the separate refund reconciliation.
-- The zero-refund-only predicate used by the credit gate stays unchanged.
CREATE FUNCTION public.provider_principal_dispute_identity(p_collection uuid,p_fact jsonb) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(p_fact->'disputed'='true'::jsonb AND CASE WHEN jsonb_typeof(p_fact->'refundedAmount')='number' THEN(p_fact->>'refundedAmount')::numeric BETWEEN 0 AND(i.inspection->>'amount')::numeric AND(p_fact->>'refundedAmount')::numeric=trunc((p_fact->>'refundedAmount')::numeric) ELSE false END AND p_fact-ARRAY['state','disputed','paymentVerified','refundedAmount'] IS NOT DISTINCT FROM i.inspection-ARRAY['state','disputed','paymentVerified','refundedAmount'],false)
 FROM public.provider_collections c JOIN public.checkout_provider_inspections i ON i.academy_id=c.academy_id AND i.id=c.inspection_id WHERE c.id=p_collection
$$;
DO $$ DECLARE d text;needle text;replacement text;BEGIN
 d=pg_get_functiondef('public.provider_dispute_release_basis(uuid,date)'::regprocedure);
 needle=$q$IF EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=c.academy_id AND collection_id=c.id) THEN RETURN jsonb_build_object('eligible',false,'code','DISPUTE_LOSS_RESOLUTION_REVIEW_REQUIRED');END IF;$q$;
 IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_BLOCK_BASE_CHANGED';END IF;d=replace(d,needle,'');
 needle=$q$principal.inspection->'disputed'='false'::jsonb AND(principal.inspection->>'state'='captured' OR(principal.inspection->>'state'='requires_review' AND(principal.inspection->>'refundedAmount')::numeric>0))$q$;
 replacement='(('||needle||$q$) OR(principal.inspection->'disputed'='true'::jsonb AND principal.inspection->>'state'='requires_review' AND EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=c.academy_id AND collection_id=c.id)))$q$;
 IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_IDENTITY_BASE_CHANGED';END IF;d=replace(d,needle,replacement);
 needle='public.provider_dispute_return_eligible(s,identity_ok,complete)';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_ELIGIBILITY_BASE_CHANGED';END IF;d=replace(d,needle,'public.provider_dispute_resolution_eligible(s,identity_ok,complete)');
 needle=$q$'code','DISPUTE_RETURN_RECONCILIATION_REQUIRED'$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_CODE_BASE_CHANGED';END IF;d=replace(d,needle,$r$'code',CASE WHEN EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=c.academy_id AND collection_id=c.id) THEN 'DISPUTE_LOSS_RESOLUTION_REVIEW_REQUIRED' ELSE 'DISPUTE_RETURN_RECONCILIATION_REQUIRED' END$r$);
 needle=$q$ ) b;
 stamp=encode$q$;replacement=$r$ UNION ALL SELECT 'loss',l.id,to_jsonb(l) FROM public.provider_dispute_losses l WHERE l.academy_id=c.academy_id AND l.collection_id=c.id
 ) b;
 stamp=encode$r$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_BOOK_BASE_CHANGED';END IF;EXECUTE replace(d,needle,replacement);
 d=pg_get_functiondef('public.provider_dispute_release_privacy()'::regprocedure);needle=$q$WHERE d.academy_id=NEW.academy_id AND d.collection_id=(NEW.payload->>'collectionId')::uuid))) unique_bindings$q$;replacement=$r$WHERE d.academy_id=NEW.academy_id AND d.collection_id=(NEW.payload->>'collectionId')::uuid) OR p.id IN(SELECT approval_id FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND collection_id=(NEW.payload->>'collectionId')::uuid))) unique_bindings$r$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_PRIVACY_BASE_CHANGED';END IF;EXECUTE replace(d,needle,replacement);
 d=pg_get_functiondef('public.provider_credit_review_required(uuid,date)'::regprocedure);needle=$q$latest.inspection->>'state'<>'captured'$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_CURRENT_PRINCIPAL_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'('||needle||' AND NOT(release_ok AND public.provider_principal_dispute_only(c.id,latest.inspection)))');
 d=pg_get_functiondef('public.provider_credit_review_basis(uuid,uuid[])'::regprocedure);needle=$q$principal.inspection->'disputed' IS DISTINCT FROM 'false'::jsonb$q$;IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_REFUND_PRINCIPAL_BASE_CHANGED';END IF;d=replace(d,needle,'('||needle||' AND NOT(release_ok AND public.provider_principal_dispute_identity(c.id,principal.inspection)))');
 needle='public.provider_principal_dispute_only(c.id,bad.inspection)';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'LOSS_RELEASE_REFUND_HISTORY_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'public.provider_principal_dispute_identity(c.id,bad.inspection)');
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_resolution_eligible(jsonb,boolean,boolean),public.provider_principal_dispute_identity(uuid,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_resolution_eligible(jsonb,boolean,boolean),public.provider_principal_dispute_identity(uuid,jsonb) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 336 $$;
